<script setup>
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';
import {native,api,state,rooms as fallbackRooms,on} from './native.js';
const rooms=computed(()=>state.voiceRooms.length?state.voiceRooms:fallbackRooms);
import Icon from './Icon.vue';
import {createMusicAppearanceGate} from '../../../packages/engine/core/music-appearance.mjs';
import AppSelect from './AppSelect.vue';import AppOverlay from './AppOverlay.vue';import {lyricLines} from '../../../packages/engine/core/lyrics.mjs';
const props=defineProps({visible:Boolean,settings:Object});
const emit=defineEmits(['open']);
const appearance=ref({owner:'',connected:false,earned:false,classic:false,unlockPending:false});
const appearanceOwner=computed(()=>state.user?.uid?JSON.stringify([state.server,state.user.uid]):'');
const appearanceGate=createMusicAppearanceGate({storage:localStorage,onChange:value=>appearance.value=value,loadEffects:async()=>{
 const response=await api('/api/linking/features');return response.effects;
}});
const appearanceEarned=computed(()=>!!appearanceOwner.value&&state.connected&&appearance.value.owner===appearanceOwner.value&&appearance.value.earned);
const archiveAppearance=computed(()=>appearanceEarned.value&&!appearance.value.classic&&!appearance.value.unlockPending);
const unlockOpen=computed(()=>props.visible&&appearanceEarned.value&&appearance.value.unlockPending);
watch(()=>[appearanceOwner.value,state.connected],([owner,connected])=>appearanceGate.setSession(owner,connected),{immediate:true});
watch(()=>props.visible,visible=>{if(visible)void appearanceGate.refresh();});
watch(unlockOpen,open=>{if(open)appearanceGate.markUnlockShown();},{immediate:true});
function closeUnlock(){appearanceGate.setArchive(false);appearanceGate.dismissUnlock();}
function openArchive(){appearanceGate.setArchive(true);appearanceGate.dismissUnlock();}
function refreshAppearance(){void appearanceGate.refresh();}
window.addEventListener('hxz-linking-progress',refreshAppearance);
window.addEventListener('focus',refreshAppearance);
const items=ref([]),results=ref([]),query=ref(''),link=ref(''),notice=ref(''),busy=ref(false),active=ref(''),playing=ref(false),loading=ref(false),position=ref(0),duration=ref(0),volume=ref(.5),room=ref('music'),sharing=ref(false),mode=ref('list');
watch(rooms,v=>{if(v.length&&!v.some(r=>r.id===room.value))room.value=v.find(r=>r.kind==='music')?.id||v[0].id;},{immediate:true});
const lyrics=ref([]),lyricError=ref(''),candidates=ref([]),lyricBusy=ref(false),floating=ref(false),consent=ref(false),account=ref({allowed:false,loggedIn:false}),accountError=ref(''),privateAudio=ref(false),lyricList=ref();let lyricRun=0;
const lyricIndex=computed(()=>lyrics.value.findLastIndex(line=>line.time<=position.value)),line=computed(()=>lyrics.value[Math.max(0,lyricIndex.value)]);
async function accountStatus(){try{account.value=await native('music',{action:'account.status'});accountError.value='';}catch(e){accountError.value=e.message;account.value={allowed:false,loggedIn:false};}}
async function login(){await action(async()=>{await native('music',{action:'account.login',accepted:true});consent.value=false;await accountStatus();});}
async function logout(){if(privateAudio.value)pause();await action(async()=>{await native('music',{action:'account.logout'});await accountStatus();});}
async function loadLyrics(netId){const run=++lyricRun;lyrics.value=[];candidates.value=[];lyricError.value='';if(!current.value)return;lyricBusy.value=true;try{const id=netId||current.value.lyricsNetId||current.value.netId;if(!id){const r=await native('music',{action:'search',query:current.value.title+' '+current.value.artist});if(run===lyricRun)candidates.value=r.items.slice(0,8);}else{const r=await native('music',{action:'lyrics',id});if(run===lyricRun)lyrics.value=lyricLines(r.original,r.translation);}}catch(e){if(run===lyricRun)lyricError.value=e.message;}finally{if(run===lyricRun)lyricBusy.value=false;}}
async function bindLyrics(t){if(!current.value)return;current.value.lyricsNetId=t.netId;persist();await loadLyrics(t.netId);}
watch(active,()=>loadLyrics());watch(lyricIndex,()=>{const box=lyricList.value,node=box?.querySelector('[aria-current=true]');if(box&&node)box.scrollTo({top:node.offsetTop-box.offsetTop-box.clientHeight/2+node.clientHeight/2,behavior:props.settings.animations&&!matchMedia('(prefers-reduced-motion: reduce)').matches?'smooth':'instant'});});
const removeAccessListener=on('music-access-changed',()=>{if(privateAudio.value)pause();void accountStatus();});watch(()=>state.user.uid,()=>{if(privateAudio.value)pause();void accountStatus();});
const current=computed(()=>items.value.find(x=>x.id===active.value));
const audio=new Audio();audio.preload='metadata';audio.crossOrigin='anonymous';let generation=0,attempted=new Set(),timer,context,source,gain,worklet;
function persist(){localStorage.setItem('hxz-music-library',JSON.stringify(items.value));}
function add(track){if(!items.value.some(x=>x.id===track.id)&&items.value.length<500){items.value.push(track);persist();}return track;}
async function action(fn){if(busy.value)return;busy.value=true;notice.value='';try{await fn();}catch(e){if(e.message!=='已取消')notice.value=e.message;}finally{busy.value=false;}}
async function search(){await action(async()=>{results.value=(await native('music',{action:'search',query:query.value})).items;});}
async function importList(){await action(async()=>{const r=await native('music',{action:'playlist',link:link.value});let added=0;for(const t of r.items){if(items.value.length>=500)break;if(!items.value.some(x=>x.id===t.id)){add(t);added++;}}notice.value=`${r.name} · 已导入 ${added} 首，音乐库共 ${items.value.length} 首`;link.value='';});}
async function importLocal(){await action(async()=>{const r=await native('pick',{kind:'music'});add({id:r.url,title:r.name||'本地音乐',artist:'本地文件',url:r.url,source:'local'});});}
function clock(s){return Math.floor((s||0)/60)+':'+String(Math.floor((s||0)%60)).padStart(2,'0');}
function nextId(step=1){const start=items.value.findIndex(t=>t.id===active.value),n=items.value.length;if(!n)return '';for(let i=1;i<=n;i++){const t=items.value[(start+step*i+n*2)%n];if(!attempted.has(t.id))return t.id;}return '';}
async function play(id,chain=false){
 const t=items.value.find(t=>t.id===id);if(!t)return;if(!chain)attempted=new Set();const token=++generation;audio.pause();clearTimeout(timer);loading.value=true;playing.value=false;active.value=id;attempted.add(id);
 try{const prepared=t.url?{url:t.url}:await native('music',{action:'prepare',id:t.netId});if(token!==generation)return;privateAudio.value=!!prepared.privateAudio;audio.src=prepared.url;audio.volume=volume.value;timer=setTimeout(()=>{if(token===generation)failed('读取音频超时');},25000);await audio.play();if(token!==generation)return;playing.value=true;}catch(e){if(token===generation)failed(e.message);}
}
function failed(reason){clearTimeout(timer);loading.value=false;playing.value=false;notice.value=(current.value?.title||'此曲目')+' 无法播放，正在尝试下一首';const next=nextId();if(next)void play(next,true);else{audio.pause();generation++;notice.value='本轮曲目均无法播放，已停止。'+String(reason||'请检查文件或网络').slice(0,130);}}
function pause(){generation++;audio.pause();clearTimeout(timer);loading.value=false;playing.value=false;}
async function toggle(){if(playing.value||loading.value){pause();return;}if(audio.src&&active.value){try{if(privateAudio.value){await accountStatus();if(!account.value.allowed||!account.value.loggedIn)throw Error('网易云账号授权已失效');}await context?.resume();await audio.play();playing.value=true;}catch(e){failed(e.message);}}else if(items.value[0])void play(items.value[0].id);}
function skip(step){attempted=new Set();const id=nextId(step);if(id)void play(id);}
async function remove(t){if(active.value===t.id){pause();active.value='';audio.removeAttribute('src');audio.load();}items.value=items.value.filter(x=>x.id!==t.id);persist();if(t.source==='local')await native('music',{action:'remove',url:t.url}).catch(()=>{});}
audio.addEventListener('playing',()=>{clearTimeout(timer);loading.value=false;playing.value=true;if(notice.value.includes('正在尝试下一首'))notice.value='已跳过不可播放的曲目，继续播放 '+(current.value?.title||'下一首');});
audio.addEventListener('timeupdate',()=>position.value=audio.currentTime);
audio.addEventListener('durationchange',()=>duration.value=Number.isFinite(audio.duration)?audio.duration:0);
audio.addEventListener('error',()=>{if(active.value&&(playing.value||loading.value))failed('音频格式或链接不可用');});
audio.addEventListener('ended',()=>{attempted=new Set();void play(mode.value==='one'?active.value:nextId());});
watch(volume,value=>{audio.volume=Number(value);});
async function listen(){await action(async()=>{
 if(state.room){notice.value='正在当前房间收听，通话设置保持不变。更换房间请到语音大厅。';return;}
 const target=room.value,previous={muted:state.muted,deafened:state.deafened};
 await native('voiceSettings',{muted:true,deafened:false});
 try{await native('voiceJoin',{room:target});notice.value='正在加入 '+(rooms.value.find(r=>r.id===target)?.name||target)+'，麦克风保持关闭';}
 catch(error){if(!state.room)await native('voiceSettings',previous).catch(()=>{});throw error;}
});}
async function stopShare(){sharing.value=false;worklet?.port.postMessage(false);await native('musicShare',{enabled:false}).catch(()=>{});}
async function share(){if(sharing.value){await stopShare();return;}await action(async()=>{if(!state.room)throw Error('请先加入一个语音房间');
 if(!context){context=new AudioContext({sampleRate:48000});await context.audioWorklet.addModule(new URL('./music-capture.js',import.meta.url));source=context.createMediaElementSource(audio);gain=context.createGain();gain.gain.value=1;source.connect(gain).connect(context.destination);worklet=new AudioWorkletNode(context,'hxz-music-capture');source.connect(worklet).connect(context.destination);worklet.port.onmessage=e=>{if(!sharing.value)return;const bytes=new Uint8Array(e.data);let raw='';for(const b of bytes)raw+=String.fromCharCode(b);window.HXZNative?.musicPCM?.(btoa(raw));};}
 await context.resume();await native('musicShare',{enabled:true});sharing.value=true;worklet.port.postMessage(true);notice.value='正在分享播放器声音，麦克风状态保持不变';});}
watch(()=>state.room,value=>{if(value)room.value=value;if(sharing.value)void stopShare();});
function hidden(){if(document.hidden){pause();void stopShare();}else void accountStatus();}
onMounted(()=>{void accountStatus();try{items.value=JSON.parse(localStorage.getItem('hxz-music-library')||'[]').filter(x=>x&&typeof x.id==='string').slice(0,500);}catch{}if(props.settings.music){add({id:props.settings.music,title:'原背景音乐',artist:'本地文件',url:props.settings.music,source:'local'});props.settings.music='';}document.addEventListener('visibilitychange',hidden);});
onBeforeUnmount(()=>{appearanceGate.dispose();window.removeEventListener('hxz-linking-progress',refreshAppearance);window.removeEventListener('focus',refreshAppearance);removeAccessListener();lyricRun++;pause();void stopShare();context?.close();audio.removeAttribute('src');audio.load();document.removeEventListener('visibilitychange',hidden);});
</script>
<template>
<section v-show="visible" class="content-page music-page" :class="{'music-archive-appearance':archiveAppearance}">
 <header class="page-toolbar"><h1>{{archiveAppearance?'音乐档案':'音乐播放器'}}</h1><span class="tag">{{items.length}} / 500 首</span><AppSelect v-if="appearanceEarned" :model-value="archiveAppearance?'archive':'classic'" label="音乐外观" :options="[{value:'archive',label:'档案样式'},{value:'classic',label:'经典样式'}]" @update:model-value="appearanceGate.setArchive($event==='archive')"/></header>
 <div v-if="archiveAppearance" class="music-archive-heading"><div class="music-archive-disc" aria-hidden="true"><Icon name="music"/></div><div><small>LINKING / MUSIC ARCHIVE</small><h2>回声已归档</h2><p>在自己的音乐中，继续这一段旅程。</p></div></div>
 <div v-if="notice" class="card music-notice" role="status"><p>{{notice}}</p><button class="icon-button" aria-label="关闭音乐提示" @click="notice=''"><Icon name="close"/></button></div>
 <section class="card music-now">
  <div class="music-current"><div class="music-track-icon"><Icon name="music"/></div><div><small>正在播放</small><h2>{{current?.title||'选一首喜欢的音乐'}}</h2><p class="muted">{{current?.artist||'导入本地歌曲，或在线搜索'}}</p></div></div>
  <div class="music-progress"><input type="range" min="0" :max="duration||1" :value="position" step=".1" :disabled="!current" aria-label="播放进度" @change="audio.currentTime=Number($event.target.value)"><div><small>{{clock(position)}}</small><small>{{clock(duration)}}</small></div></div>
  <div class="music-buttons"><button class="soft-button" aria-label="上一首" :disabled="!items.length" @click="skip(-1)"><Icon name="previous"/></button><button class="primary" :disabled="!items.length" @click="toggle"><Icon :name="playing||loading?'pause':'play'"/>{{loading?'取消加载':playing?'暂停':'播放'}}</button><button class="soft-button" aria-label="下一首" :disabled="!items.length" @click="skip(1)"><Icon name="next"/></button></div>
  <div class="music-playback-options"><label class="music-volume">音量<input v-model.number="volume" type="range" min="0" max="1" step=".05" aria-label="音乐音量"></label><AppSelect v-model="mode" label="播放方式" :options="[{value:'list',label:'列表循环'},{value:'one',label:'单曲循环'}]"/></div>
  <details class="music-lyrics" :open="!!current"><summary>歌曲歌词</summary><div class="music-lyric-tools"><button class="soft-button" :disabled="!current" @click="floating=!floating">{{floating?'收回悬浮歌词':'其他页面显示歌词'}}</button><button class="icon-button" aria-label="刷新歌词" :disabled="lyricBusy||!current" @click="loadLyrics()"><Icon name="refresh"/></button></div><div ref="lyricList" class="mobile-lyrics-list"><button v-for="(row,i) in lyrics" :key="i" :aria-current="i===lyricIndex" @click="audio.currentTime=row.time"><span>{{row.text}}</span><small v-if="row.translation">{{row.translation}}</small></button><p v-if="!lyrics.length" class="empty-note">{{lyricBusy?'正在获取歌词…':lyricError||(!current?'播放歌曲后查看同步歌词':'暂无同步歌词')}}</p></div><div v-if="candidates.length" class="music-lyric-candidates"><p class="muted">为本地音乐选择对应歌词</p><button v-for="candidate in candidates" :key="candidate.id" class="soft-button" @click="bindLyrics(candidate)">{{candidate.title}} · {{candidate.artist}}</button></div></details>
 </section>
 <section class="card music-library"><header class="music-section-heading"><div><h2>我的音乐</h2><p class="muted">{{items.length}} 首歌曲 · 保存在此设备</p></div><button class="soft-button" :disabled="busy||items.length>=500" @click="importLocal"><Icon name="plus"/>导入音乐</button></header><p v-if="!items.length" class="empty-note">导入普通音频、常见 NCM 或旧 QMC，也可添加在线搜索结果。单曲最多 50 MB。</p><div v-else class="music-list"><div v-for="t in items" :key="t.id" class="music-song" :class="{selected:t.id===active}"><button class="song-play" :title="t.title+' · '+t.artist" @click="play(t.id)"><Icon :name="active===t.id&&playing?'music':'play'"/><span><strong>{{t.title}}</strong><small>{{t.artist}}</small></span></button><button class="icon-button" :aria-label="'移除 '+t.title" @click="remove(t)"><Icon name="close"/></button></div></div></section>
 <section class="card music-online form-stack"><header class="music-section-heading"><div><h2>在线搜索</h2><p class="muted">网易云音乐与公开歌单</p></div></header><div class="mobile-music-account"><div class="music-account-copy"><strong>{{account.loggedIn?'个人网易云账号已登录':'使用自己的网易云账号'}}</strong><small>{{accountError||(account.allowed?'登录状态仅保存在此设备':'此功能需要社区管理员授权')}}</small></div><div class="music-account-actions"><button v-if="account.loggedIn" class="soft-button" :disabled="busy" @click="logout">退出账号</button><button v-else class="soft-button" :disabled="!account.allowed||busy" @click="consent=true">登录账号</button><button class="icon-button" aria-label="刷新网易云登录状态" @click="accountStatus"><Icon name="refresh"/></button></div></div><form class="music-search" @submit.prevent="search"><label><span>搜索歌曲</span><input v-model="query" placeholder="歌曲名或歌手" maxlength="200" aria-label="搜索歌曲"></label><button class="soft-button" :disabled="busy||!query.trim()"><Icon name="search"/>搜索</button></form><form class="music-search" @submit.prevent="importList"><label><span>导入公开歌单</span><input v-model="link" placeholder="歌单链接或 ID" aria-label="网易云歌单链接"></label><button class="soft-button" :disabled="busy||!link.trim()">导入歌单</button></form><p class="muted">未登录时使用可用外链；登录后按你的账号权限播放。受限曲目会自动跳过。</p><div v-if="results.length" class="music-list search-results"><button v-for="t in results" :key="t.id" class="music-song" :title="t.title+' · '+t.artist" @click="add(t);play(t.id)"><Icon name="plus"/><span><strong>{{t.title}}</strong><small>{{t.artist}}</small></span></button></div></section>
 <section class="card music-together form-stack"><header class="music-section-heading"><div><h2>一起听</h2><p class="muted">与同一语音房间的伙伴分享音乐</p></div></header><p v-if="state.room" class="music-current-room">当前房间：{{rooms.find(r=>r.id===state.room)?.name||state.room}} · 分享至此房间</p><AppSelect v-else v-model="room" label="选择收听房间" :options="rooms.map(r=>({value:r.id,label:r.name}))"/><div class="music-room-actions"><button class="soft-button" :disabled="busy||!state.connected||!!state.room" @click="listen"><Icon name="headphones"/>{{state.room?'正在当前房间收听':'加入所选房间收听'}}</button><button class="soft-button" :disabled="!state.room||busy" :aria-pressed="sharing" @click="share">{{sharing?'停止分享':'分享播放器'}}</button></div><p class="muted">{{!state.connected?'登录并连接社区后加入收听。':state.room?'当前频道：'+(rooms.find(r=>r.id===state.room)?.name||state.room)+'。':'加入房间后收听，默认不开麦。'}}更换房间请到语音大厅。切换页面继续播放，进入后台暂停音乐分享。</p></section>
</section>
<Teleport to="#mobile-music-dock" defer><aside v-if="!visible&&current" class="mobile-music-dock" :class="{expanded:floating}"><button class="icon-button" :aria-label="playing?'暂停音乐':'播放音乐'" @click="toggle"><Icon :name="playing?'pause':'play'"/></button><button class="music-dock-open" :aria-label="'打开音乐播放器：'+current.title" @click="emit('open')"><small>{{current.title}}</small><strong v-if="floating">{{line?.text||(lyricBusy?'正在获取歌词…':lyricError||'暂无歌词')}}</strong><span v-if="floating&&line?.translation">{{line.translation}}</span></button><button class="icon-button" :aria-label="floating?'收回歌词':'展开歌词'" @click="floating=!floating"><Icon :name="floating?'close':'music'"/></button></aside></Teleport>
<AppOverlay :open="unlockOpen" label="音乐档案已解锁" @close="closeUnlock"><section class="sheet music-unlock-sheet" :class="{'reduce-motion':settings.animationSpeed===0||settings.animations===false}"><header class="sheet-header"><h2>音乐档案已解锁</h2><button class="icon-button" aria-label="关闭解锁提示" @click="closeUnlock"><Icon name="close"/></button></header><div class="sheet-body music-unlock-content"><div class="music-unlock-emblem" aria-hidden="true"><Icon name="music"/></div><p>回声已归档。你完成了 LINKING 音乐外观任务，现在可以进入音乐档案，也可继续使用经典播放器。</p><div class="music-unlock-actions"><button class="soft-button" @click="closeUnlock">继续经典样式</button><button class="primary" @click="openArchive">进入音乐档案</button></div></div></section></AppOverlay>
<AppOverlay :open="consent" label="登录个人网易云账号" @close="consent=false"><section class="sheet"><header class="sheet-header"><h2>登录个人网易云账号</h2><button class="icon-button" aria-label="关闭登录说明" @click="consent=false"><Icon name="close"/></button></header><div class="sheet-body form-stack"><p>接下来打开网易云官方登录页面。请只登录你自己的账号。</p><p>登录状态只保存在此设备，不会传给社区管理员或其他玩家。在公用设备使用后请退出。</p><p>第三方播放器可能触发验证码、异地登录或账号风控。可播放内容由你的账号、会员和版权权限决定，社区授权不会提供额外的曲目权限。</p><div class="actions"><button class="soft-button" @click="consent=false">取消</button><button class="primary" :disabled="busy" @click="login">同意并打开官方登录</button></div><p v-if="notice" class="error-note">{{notice}}</p></div></section></AppOverlay>
</template>
